import {FC} from "react";
import {clsx} from "clsx";
import style from './Buttons.module.scss';
import {svgIcons} from "../../../assets/svgIcons";

interface IWalletButtons {
    className?: string
}

export const Buttons: FC<IWalletButtons> = ({className}) => {
    return (
        <div className={clsx(style.buttons, Boolean(className) && className)}>
            {
                [
                    {
                        label: 'Create Token On Solana',
                        icon: svgIcons.button_0,
                    },
                    {
                        label: 'Create + Launch On PumpFun',
                        icon: svgIcons.button_1,
                    },
                    {
                        label: 'Swap on Jupiter',
                        icon: svgIcons.button_2,
                    },
                ].map(({label, icon}, key) => (
                    <div key={key}
                         className={style.item}
                    >
                        {icon}
                        <button>
                            <p>{label}</p>
                        </button>
                    </div>
                ))
            }
        </div>
    )
}