import style from "./RadarAnimation.module.scss"
import {FC, useRef} from "react";
import {clsx} from "clsx";
import {svgIcons} from "../../../assets/svgIcons";
import {useGSAP} from "@gsap/react";
import gsap from "gsap";

interface IRadarAnimation {
    className?: string
}

export const RadarAnimation: FC<IRadarAnimation> = ({className}) => {

    const appRef = useRef<HTMLDivElement>(null!);

    const duration_circles = 4;
    const duration_rotate = 8;


    useGSAP(() => {

        gsap.timeline({repeat: -1})
            .to('.circles', {
                scale: 0.8,
                duration: duration_circles,
                ease: 'power1.out'
            })
            .to('.circles', {
                scale: 1,
                duration: duration_circles,
                //ease: 'power1.in'
            })


        gsap.timeline({repeat: -1})
            .to('.lineWrapper', {
                rotate: '-360deg',
                duration: duration_rotate,
                ease: "none",
            })

        gsap.timeline({repeat: -1})
            .to('.dot_2', {
                opacity: 1,
                duration: 0.5,
                delay: 5,
            })
            .to('.dot_2', {
                opacity: 0.3,
                duration: 0.5,
            })
            .to('.dot_2', {
                opacity: 0.3,
                duration: 2,
            })


        gsap.timeline({repeat: -1})
            .to('.dot_4', {
                opacity: 1,
                duration: 0.5,
                delay: 1,
            })
            .to('.dot_4', {
                opacity: 0.3,
                duration: 0.5,
            })
            .to('.dot_4', {
                opacity: 0.3,
                duration: 6,
            })

        gsap.timeline({repeat: -1})
            .to('.dot_5', {
                opacity: 1,
                duration: 0.5,
                delay: 7,
            })
            .to('.dot_5', {
                opacity: 0.3,
                duration: 0.5,
            })

        gsap.timeline({repeat: -1})
            .to('.dot_6', {
                opacity: 1,
                duration: 0.5,
            })
            .to('.dot_6', {
                opacity: 0.3,
                duration: 0.5,
            })
            .to('.dot_6', {
                opacity: 0.3,
                duration: 7,
            })

    }, {scope: appRef})

    return (
        <div className={clsx(style.radarAnimation, Boolean(className) && className)}
             ref={appRef}
        >

            <div className={style.logo}>
                {svgIcons.logo_blue_outline}
            </div>

            <div className={style.line_vertical}/>
            <div className={style.line_horizontal}/>


            <div className={clsx(style.circles, 'circles')}>
                <div/>
                <div/>
                <div/>
                <div/>
            </div>

            <div className={clsx(style.lineWrapper, 'lineWrapper')}>
                {svgIcons.line_shadow}
            </div>

            <div className={clsx(style.dot, style.dot_1)}/>
            <div className={clsx(style.dot, style.dot_2, 'dot_2')}/>
            <div className={clsx(style.dot, style.dot_3)}/>
            <div className={clsx(style.dot, style.dot_4, 'dot_4')}/>
            <div className={clsx(style.dot, style.dot_5, 'dot_5')}/>
            <div className={clsx(style.dot, style.dot_6, 'dot_6')}/>
            <div className={clsx(style.dot, style.dot_7)}/>

        </div>
    )
}