import style from './Preloader.module.scss'
import {svgIcons} from "../../assets/svgIcons";
import {useGSAP} from "@gsap/react";
import gsap from "gsap";
import {useRef} from "react";
import {RadarAnimation} from "../_common/RadarAnimation/RadarAnimation";

export const Preloader = () => {

    const appRef = useRef<HTMLDivElement>(null!);

    const duration = 0.5;

    useGSAP(() => {
        gsap.timeline({repeat: -1})
            .set('.d_1', {opacity: 0})
            .set('.d_2', {opacity: 0})
            .set('.d_3', {opacity: 0})


            .to('.d_1', {opacity: 0, duration})
            .set('.d_1', {opacity: 1})

            .to('.d_1', {opacity: 1, duration})
            .set('.d_2', {opacity: 1})

            .to('.d_1', {opacity: 1, duration})
            .set('.d_3', {opacity: 1})

            .to('.d_1', {opacity: 1, duration})



    }, {scope: appRef})


    return (
        <div className={style.preloader}
             ref={appRef}
        >

            <RadarAnimation className={style.radarAnimation}/>

            {svgIcons.logo}
            <p>
                <span>Website is Loading</span><span className='d_1'>.</span><span className='d_2'>.</span><span className='d_3'>.</span>
            </p>

        </div>
    )
}