import style from './ChatPage.module.scss';
import {svgIcons} from "../../assets/svgIcons";
import back from '../../assets/png/chat_back.png';
import {Buttons} from "../_common/Buttons/Buttons";
import {useFormik} from "formik";
import {FormikHelpers} from "formik/dist/types";

interface IValues {
    message: string
}


export const ChatPage = () => {

    const onSubmit = (values: IValues, formikHelpers: FormikHelpers<IValues>) => {
        try {
            console.log(values)
            formikHelpers.resetForm();
        } catch (e: any) {
            console.log(e.message)
        }
    }

    const formik = useFormik({
        initialValues: {
            message: ''
        },
        onSubmit
    })


    return (
        <div className={style.chatPage}>

            <img src={back} alt="" className={style.back}/>

            <div className={style.inner}>

                {svgIcons.logo_sign}

                <h1 className={style.title}>
                    Hi, I'm Your XZYPHER Agent
                </h1>

                <p className={style.description}>
                    Welcome! I’ll help you easily handle token swaps, launches, and blockchain tasks
                </p>

                <div className={style.card}>

                    <p>Connect wallet to use</p>

                    <div className={style.field}>
                        <div>
                            {svgIcons.phantom}
                            <p>Phantom</p>
                        </div>
                        {svgIcons.arrowRight}
                    </div>

                </div>

                <Buttons className={style.buttons}/>

                <form onSubmit={formik.handleSubmit}
                      className={style.form}
                >
                    <input type="text"
                           placeholder='Type your message here'
                           {...formik.getFieldProps('message')}

                    />
                </form>


            </div>
        </div>
    )
}