import style from './TopCards.module.scss'
// @ts-ignore
import src from '../../../assets/mp4/ai_driven.mp4';
import {Swiper, SwiperSlide} from 'swiper/react';
import 'swiper/css';
import {svgIcons} from "../../../assets/svgIcons";


export const TopCards = () => {
    return (
        <div className={style.topCards}>

            <div className={style.card}>
                <p className={style.cardTitle}>
                    Enterprise-Level API
                </p>

                <div className={style.swiperWrapper}>
                    <Swiper slidesPerView='auto'
                            centeredSlides={true}
                            className={style.swiper}
                            spaceBetween={12}
                    >
                        {
                            [
                                {
                                    icon: svgIcons.logo_blue,
                                    label: 'api.XZYPHER',
                                    text: 'Command your agent to execute swaps, automate tasks, and maintain an edge in the ever-evolving blockchain landscape.'
                                },
                                {
                                    icon: svgIcons.logo_blue,
                                    label: 'api.XZYPHER',
                                    text: 'Command your agent to execute swaps, automate tasks, and maintain an edge in the ever-evolving blockchain landscape.'
                                },
                                {
                                    icon: svgIcons.logo_blue,
                                    label: 'api.XZYPHER',
                                    text: 'Command your agent to execute swaps, automate tasks, and maintain an edge in the ever-evolving blockchain landscape.'
                                },
                            ].map(({icon, label, text}, key) => (
                                <SwiperSlide key={key}
                                             className={style.slide}

                                >
                                    <div className={style.top}>
                                        {icon}<p>{label}</p>
                                    </div>
                                    <p>{text}</p>
                                </SwiperSlide>
                            ))
                        }
                    </Swiper>
                </div>

            </div>

            <div className={style.card}>
                <video src={src}
                       playsInline={true}
                       muted={true}
                       autoPlay={true}
                       loop={true}
                />
                <p className={style.cardTitle}>
                    AI-Driven Analytical Engine Section
                </p>
                <p className={style.text}>
                    XZYPHER gathers and processes intelligence from every source, including global economic events, social trends, and on-chain activity.
                </p>
            </div>

        </div>
    )
}