import style from './Transform.module.scss';
import back from '../../assets/png/transform_back.png';
export const Transform = () => {
    return (
        <div className={style.transform}>

            <img src={back} alt="" className={style.back}/>

            <div className={style.inner}>

                <h2 className={style.title}>
                    Transform Your DeFi Strategy
                </h2>

                <p>
                    XZYPHER is the AI agent redefining how you trade, manage, and launch tokens in the DeFi ecosystem.
                </p>

                <a href='#' target='_blank' rel='noreferrer noopener nofollow'>
                    <span>Docs</span>
                </a>

            </div>
        </div>
    )
}