import {action, makeObservable, observable} from "mobx";

export class AppStore {
    burgerMenuOpen = false

    constructor() {
        makeObservable(this,
            {
                burgerMenuOpen: observable,

                setBurgerMenuOpen: action.bound,
            }
        )
    }

    setBurgerMenuOpen(burgerMenuOpen: boolean) {
        this.burgerMenuOpen = burgerMenuOpen;
    }


}