import style from './BottomCards.module.scss'
import {clsx} from "clsx";
import {RunningStringItem} from "../../_common/RunningStringItem/RunningStringItem";
import {RadarAnimation} from "../../_common/RadarAnimation/RadarAnimation";

export const BottomCards = () => {
    return (
        <div className={style.bottomCards}>

            <div className={style.top}>

                <div className={style.card}>

                    <div className={style.rows}>

                        <div className={style.textRowWrapper}>
                            <RunningStringItem forward={false}
                                               duration={40}
                                               count={2}
                                               item={
                                                   <div className={clsx(style.textRow, style.textRow_1)}>
                                                       {
                                                           ['Cross-chain Analysis', 'SmartSwap', 'Create & Launch PumpFun', 'Token Builder']
                                                               .map((text, key) => (
                                                                   <p key={key}>
                                                                       {text}
                                                                   </p>
                                                               ))
                                                       }
                                                   </div>
                                               }
                            />
                        </div>

                        <div className={style.textRowWrapper}>
                            <RunningStringItem forward={false}
                                               duration={40}
                                               count={2}
                                               item={
                                                   <div className={clsx(style.textRow, style.textRow_2)}>
                                                       {
                                                           ['Instant On Chain Analysis', 'Instant Liquidity Pools', 'Create & Launch PumpFun', 'Pattern Recognition']
                                                               .map((text, key) => (
                                                                   <p key={key}>
                                                                       {text}
                                                                   </p>
                                                               ))
                                                       }
                                                   </div>
                                               }
                            />
                        </div>

                        <div className={style.textRowWrapper}>
                            <RunningStringItem forward={false}
                                               duration={40}
                                               count={2}
                                               item={
                                                   <div className={clsx(style.textRow, style.textRow_3)}>
                                                       {
                                                           ['Rug Checker', 'Wallet Tracker', 'Pattern Recognition', 'Pattern Recognition']
                                                               .map((text, key) => (
                                                                   <p key={key}>
                                                                       {text}
                                                                   </p>
                                                               ))
                                                       }
                                                   </div>
                                               }
                            />
                        </div>

                    </div>

                    <div className={style.texts}>
                        <p>
                            Tell Your Agent Everything
                        </p>
                        <p>
                            Directly handle swaps, token launches, and staking through the chat interface, bypassing the
                            need for external tabs or manual input.
                        </p>
                    </div>


                </div>

                <div className={style.card}>

                    <div className={style.items}>

                        <div className={style.itemsRowWrapper}>
                            <RunningStringItem forward={false}
                                               duration={40}
                                               count={2}
                                               item={
                                                   <div className={style.itemsRow}>
                                                       {
                                                           [
                                                               {
                                                                   value: '<3%',
                                                                   text: 'Error Rate'
                                                               },
                                                               {
                                                                   value: '97%',
                                                                   text: 'Success Rate'
                                                               },
                                                               {
                                                                   value: '< 1 Sec',
                                                                   text: 'Response Time'
                                                               },
                                                               {
                                                                   value: '< 2 Sec',
                                                                   text: 'Transaction Speed'
                                                               },
                                                           ].map(({value, text}, key) => (
                                                               <div key={key}
                                                                    className={style.item}
                                                               >
                                                                   <p>{value}</p>
                                                                   <p>{text}</p>
                                                               </div>
                                                           ))
                                                       }
                                                   </div>
                                               }
                            />
                        </div>
                        <div className={style.row}>
                            {
                                [
                                    {
                                        value: '<3%',
                                        text: 'Error Rate'
                                    },
                                    {
                                        value: '97%',
                                        text: 'Success Rate'
                                    },
                                    {
                                        value: '< 1 Sec',
                                        text: 'Response Time'
                                    },
                                    {
                                        value: '< 2 Sec',
                                        text: 'Transaction Speed'
                                    },
                                ].map(({value, text}, key) => (
                                    <div key={key}
                                         className={style.item}
                                    >
                                        <p>{value}</p>
                                        <p>{text}</p>
                                    </div>
                                ))
                            }
                        </div>
                    </div>

                    <div className={style.texts}>
                        <p>Intelligence Metrics</p>
                        <p>Insights at a glance</p>
                    </div>


                </div>


            </div>

            <div className={clsx(style.bottom, style.card)}>
                <RadarAnimation className={style.radarAnimation}/>
                {/*<video src={src}*/}
                {/*       playsInline={true}*/}
                {/*       muted={true}*/}
                {/*       autoPlay={true}*/}
                {/*       loop={true}*/}
                {/*/>*/}
                <div>
                    <p>
                        Action-Driven Insight Engine
                    </p>
                    <p>
                        By analyzing millions of signals in real-time, it cuts through market noise, providing clear,
                        actionable intelligence.
                    </p>
                </div>

            </div>

        </div>
    )
}