import style from './Faq.module.scss'
import {TitleWithLines} from "../_common/TitleWithLines/TitleWithLines";
import {FC, useState} from "react";
import {svgIcons} from "../../assets/svgIcons";
import Collapse from '@mui/material/Collapse';

export const Faq = () => {
    return (
        <div className={style.faq}>
            <div className={style.inner}>

                <TitleWithLines title='FAQS'/>

                <h2 className={style.title}>
                    Need More Info?
                </h2>

                <div className={style.items}>
                    {
                        [
                            {
                                q: "What is XZYPHER?",
                                a: 'XZYPHER is your AI-powered agent for token swaps, Solana token launches, Pumpfun deployment, and blockchain data analysis.',
                            },
                            {
                                q: "What exactly do you do?",
                                a: 'XZYPHER is your AI-powered agent for token swaps, Solana token launches, Pumpfun deployment, and blockchain data analysis.',
                            },
                            {
                                q: "Wen Live?",
                                a: 'XZYPHER is launching soon. Follow for updates.',
                            },

                        ].map((item, key) => (
                            <FaqItem key={key} {...item}/>
                        ))
                    }
                </div>


            </div>
        </div>
    )
}

interface IFaqItem {
    q: string
    a: string
}

const FaqItem: FC<IFaqItem> = ({q, a}) => {
    const [open, setOpen] = useState(false)
    const onClick = () => setOpen(!open);

    return (
        <div className={style.item}
        >
            <div className={style.row}>
                <p>{q}</p>
                <button onClick={onClick}>
                    {open ? svgIcons.button_minus : svgIcons.button_plus}
                </button>
            </div>

            <Collapse in={open}>
                <p className={style.answer}>
                    {a}
                </p>
            </Collapse>


        </div>
    )
}