import style from './Header.module.scss';
import {Link} from "react-router-dom";
import {HashLink} from 'react-router-hash-link';
import {svgIcons} from "../../assets/svgIcons";
import {observer} from "mobx-react-lite";
import {useStore} from "../../store/rootStore";
import {clsx} from "clsx";

export const Header = observer(() => {

    const {
        appStore: {
            burgerMenuOpen, setBurgerMenuOpen
        }
    } = useStore()

    const onClose = () => setBurgerMenuOpen(false)

    return (
        <header className={style.header}>
            <div className={clsx({
                [style.inner]: true,
                [style.inner_open]: burgerMenuOpen,
            })}>
                <div className={style.top}>
                    <Link to='/'
                          className={style.logo}
                          onClick={onClose}
                    >
                        {svgIcons.logo}
                    </Link>

                    <div className={style.right}>

                        <div className={style.links}>

                            <Link to='/'
                                  className={style.link}
                            >
                                Home
                            </Link>

                            <HashLink to='/#Features'
                                      className={style.link}
                                      smooth={true}
                            >
                                Features
                            </HashLink>

                            <a href="https://xzyphersoliz.gitbook.io/xzypher"
                               className={style.link}
                               target='_blank'
                               rel='noreferrer noopener nofollow'
                            >
                                Whitepaper
                            </a>

                        </div>

                        <Link to='/chat'
                              className={style.chat}
                        >
                            XZYPHER AI Chat
                        </Link>

                        <a href="https://x.com/XzypherSoliz"
                           target='_blank'
                           rel='noreferrer noopener nofollow'
                           className={style.x}
                        >
                            {svgIcons.x}
                        </a>

                        <button className={clsx({
                            [style.burger]: true,
                            [style.burger_burgerMenuOpen]: burgerMenuOpen,
                        })}
                                onClick={() => setBurgerMenuOpen(!burgerMenuOpen)}
                        >
                            {svgIcons.burger}
                        </button>


                    </div>
                </div>

                <div className={clsx({
                    [style.content]: true,
                    [style.content_show]: burgerMenuOpen,
                })}>
                    <div className={style.links}>

                        <Link to='/'
                              className={style.link}
                              onClick={onClose}
                        >
                            Home
                        </Link>

                        <HashLink to='/#Features'
                                  className={style.link}
                                  onClick={onClose}
                        >
                            Features
                        </HashLink>

                        <a href="https://xzyphersoliz.gitbook.io/xzypher"
                           className={style.link}
                           target='_blank'
                           rel='noreferrer noopener nofollow'
                           onClick={onClose}
                        >
                            Whitepaper
                        </a>


                    </div>

                    <Link to='/chat'
                          className={style.chat}
                          onClick={onClose}
                    >
                        XZYPHER AI Chat
                    </Link>
                </div>

            </div>
        </header>
    )
})